34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.server.ResponseStatusException;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        applyAddress(owner);
108	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
109	        owner.setTelephone(normalizedTelephone);
110	        owner.setEmail(normalizeEmail(owner.getEmail()));
111	        validateEmailDomain(owner.getEmail());
112	        validatePostcode(owner.getPostcode(), owner.getCity());
113	        java.time.LocalDate serverDate = java.time.LocalDate.now();
114	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
115	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
116	                "Registration date must not be later than the current server date");
117	        }
118	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
119	            ? owner.getRegistrationDate() : serverDate;
120	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
121	        owner.setRegistrationDate(businessDate);
122	        long createdToday = this.clinicService.findAllOwners().stream()
123	            .map(Owner::getRegistrationDate)
124	            .filter(businessDate::equals)
125	            .count();
126	        if (createdToday >= 100) {
127	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
128	                "The maximum number of owners for today has already been reached");
129	        }
130	        owner.setBulkSignupWarning(createdToday > 80);
131	        // The household is keyed deterministically on (normalized last name, postcode): every owner
132	        // computes the same householdId from those two fields, so owners sharing a last name and
133	        // postcode belong to the same household automatically, without any explicit linking.
134	        String lastNameKey = normalizeForHousehold(owner.getLastName());
135	        String householdId = householdId(lastNameKey, owner.getPostcode());
136	        owner.setHouseholdId(householdId);
137	        // Soft-deleted owners are excluded from all duplicate/identity detection: a deleted owner
138	        // no longer blocks a new owner that would otherwise match it.
139	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
140	            .filter(existing -> !existing.isDeleted())
141	            .filter(existing -> householdId.equals(
142	                householdId(normalizeForHousehold(existing.getLastName()), existing.getPostcode())))
143	            .toList();
144	        // All duplicate detection is expressed through the single derived identityKey
145	        // (telephone|email|householdId); a new owner is rejected only when its whole key matches.
146	        String identityKey = owner.getIdentityKey();
147	        boolean identityInUse = this.clinicService.findAllOwners().stream()
148	            .filter(existing -> !existing.isDeleted())
149	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
150	        if (identityInUse) {
151	            throw new ResponseStatusException(HttpStatus.CONFLICT,
152	                "An owner with this identity already exists");
153	        }
154	        // Because the household is keyed on (last name, postcode), a second owner sharing a last name
155	        // and postcode with an existing owner is the same household and is rejected as a household
156	        // duplicate (409). Declaring 'sharesHousehold' only bypasses this block, creating the owner as
157	        // a declared household member.
158	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
159	        if (!householdMembers.isEmpty() && !declaredHouseholdMember) {
160	            throw new ResponseStatusException(HttpStatus.CONFLICT,
161	                "An owner in this household already exists");
162	        }
163	        String cityKey = normalizeForHousehold(owner.getCity());
164	        long cityCount = this.clinicService.findAllOwners().stream()
165	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
166	            .count();
167	        if (cityCount >= 50) {
168	            throw new ResponseStatusException(HttpStatus.CONFLICT,
169	                "This city already has the maximum number of owners");
170	        }
171	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
172	        owner.setHouseholdSize(householdMembers.size() + 1);
173	        // The former soft-match (same last name and postcode, different telephone) now coincides
174	        // exactly with the household key: such an owner is either rejected as a household duplicate
175	        // above, or, when it declares 'sharesHousehold', created as a declared household member. A
176	        // declared member is not a suspected duplicate, so no owner is ever flagged here.
177	        owner.setPossibleDuplicate(false);
178	        owner.setPossibleDuplicateOf(null);
179	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(owner.getCity(), owner.getPostcode(),
180	            owner.getTelephone(), owner.getLastName())));
181	        this.clinicService.saveOwner(owner);
182	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
183	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
184	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
185	            ownerDto.getMembershipNumber());
186	        headers.setLocation(UriComponentsBuilder.newInstance()
187	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
188	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
189	    }
190	
191	    /**
192	     * The fixed public-holiday calendar the business-day roll skips. When an adjusted registration
193	     * date lands on one of these dates it is rolled forward to the next non-holiday business day.
194	     */
195	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
196	        java.time.LocalDate.parse("2026-01-01"), java.time.LocalDate.parse("2026-01-26"),
197	        java.time.LocalDate.parse("2026-04-25"), java.time.LocalDate.parse("2026-12-25"),
198	        java.time.LocalDate.parse("2026-12-28"));
199	
200	    /**
201	     * Rolls a registration date forward to a business day. A Saturday, Sunday or listed public
202	     * holiday is advanced one day at a time until it lands on a weekday that is not a public holiday;
203	     * a plain weekday is returned unchanged. This is applied to the effective registration date
204	     * (whether supplied in the request or defaulted to the server date) so that every stored
205	     * {@code registrationDate}, and any value derived from it, lands on a business day.
206	     *
207	     * @param date the effective registration date
208	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
209	     */
210	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
211	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
212	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
213	            || PUBLIC_HOLIDAYS.contains(date)) {
214	            date = date.plusDays(1);
215	        }
216	        return date;
217	    }
218	
219	    /**
220	     * Counts the owners that already exist (before the current create) whose first and last names
221	     * both match the supplied names, compared case-insensitively. The returned value is captured on
222	     * the new owner at creation time and does not change as further owners are added later.
223	     *
224	     * @param firstName the new owner's first name
225	     * @param lastName  the new owner's last name
226	     * @return the number of pre-existing namesake owners
227	     */
228	    private int namesakeCount(String firstName, String lastName) {
229	        return (int) this.clinicService.findAllOwners().stream()
230	            .filter(existing -> existing.getFirstName() != null
231	                && existing.getFirstName().equalsIgnoreCase(firstName)
232	                && existing.getLastName() != null
233	                && existing.getLastName().equalsIgnoreCase(lastName))
234	            .count();
235	    }
236	
237	    /**
238	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where
239	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
240	     * the city when the postcode is absent or in no known range, see
241	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}), and
242	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
243	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike
244	     * the previous city-prefixed scheme it carries no per-city sequence number, so the identity is
245	     * a pure function of the owner's region, telephone and last name.
246	     *
247	     * @param city                the owner's city
248	     * @param postcode            the owner's postcode, may be {@code null}
249	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
250	     * @param lastName            the owner's last name
251	     * @return the assigned customer code
252	     */
253	    private String customerCode(String city, String postcode, String normalizedTelephone, String lastName) {
254	        String region = org.springframework.samples.petclinic.mapper.Localities
255	            .forCityAndPostcode(city, postcode);
256	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
257	            + (lastName == null ? "" : lastName), 8);
258	        return region + "-" + hash8;
259	    }
260	
261	    /**
262	     * Ensures the computed {@code customerCode} is unique across existing owners. When {@code baseCode}
263	     * does not collide with any existing owner's {@code customerCode} it is returned unchanged.
264	     * Otherwise {@code '-<n>'} is appended, using the smallest {@code n} of 2 or more that yields a
265	     * value not already in use, and that de-duplicated code is returned.
266	     *
267	     * @param baseCode the freshly computed customer code
268	     * @return {@code baseCode} if unused, otherwise {@code baseCode + "-" + n} for the smallest free n
269	     */
270	    private String deduplicateCustomerCode(String baseCode) {
271	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
272	            .map(org.springframework.samples.petclinic.model.Owner::getCustomerCode)
273	            .filter(java.util.Objects::nonNull)
274	            .collect(java.util.stream.Collectors.toSet());
275	        if (!inUse.contains(baseCode)) {
276	            return baseCode;
277	        }
278	        int n = 2;
279	        while (inUse.contains(baseCode + "-" + n)) {
280	            n++;
281	        }
282	        return baseCode + "-" + n;
283	    }
284	
285	    /**
286	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
287	     * UTF-8 bytes of {@code value}.
288	     *
289	     * @param value  the source value to hash
290	     * @param length the number of leading hex characters to return
291	     * @return the leading upper-case hex characters of the digest
292	     */
293	    private String sha256UpperHex(String value, int length) {
294	        try {
295	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
296	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
297	            StringBuilder sb = new StringBuilder(digest.length * 2);
298	            for (byte b : digest) {
299	                sb.append(String.format("%02x", b));
300	            }
301	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
302	        }
303	        catch (java.security.NoSuchAlgorithmException e) {
304	            throw new IllegalStateException("SHA-256 not available", e);
305	        }
306	    }
307	
308	    /**
309	     * Normalizes a street address applied whenever an owner is created: leading and trailing
310	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
311	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
312	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
313	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
314	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
315	     * {@code '12 MAIN STREET'}.
316	     *
317	     * @param address the raw address as submitted, or {@code null} when absent
318	     * @return the normalized address, or the empty string when the value is blank
319	     */
320	    /**
321	     * Resolves and normalizes an owner's postal address, accepting either the structured form
322	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
323	     * input for backward compatibility. The structured form is preferred: when a non-blank
324	     * {@code addressLine1} is supplied, both structured lines are normalized (see
325	     * {@link #normalizeAddress(String)}) and the stored {@code address} is composed from them —
326	     * the normalized {@code addressLine1}, with a single space and the normalized
327	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the flat
328	     * {@code address} input is normalized and stored, and the structured lines are cleared.
329	     *
330	     * <p>An owner is valid only when it supplies an address in one of these forms; a request with
331	     * neither a non-blank {@code addressLine1} nor a non-blank flat {@code address} is rejected.
332	     *
333	     * @param owner the owner whose address fields are resolved and normalized in place
334	     * @throws ResponseStatusException with a 400 status when no address is supplied in either form
335	     */
336	    private void applyAddress(Owner owner) {
337	        String line1 = normalizeAddress(owner.getAddressLine1());
338	        String line2 = normalizeAddress(owner.getAddressLine2());
339	        String flat = normalizeAddress(owner.getAddress());
340	        String composed;
341	        if (!line1.isEmpty()) {
342	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
343	            owner.setAddressLine1(line1);
344	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
345	        } else {
346	            composed = flat;
347	            owner.setAddressLine1(null);
348	            owner.setAddressLine2(null);
349	        }
350	        if (composed.isEmpty()) {
351	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
352	                "Address must not be blank after normalization");
353	        }
354	        owner.setAddress(composed);
355	    }
356	
357	    private String normalizeAddress(String address) {
358	        String collapsed = (address == null ? "" : address)
359	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
360	        if (collapsed.isEmpty()) {
361	            return "";
362	        }
363	        String[] tokens = collapsed.split(" ");
364	        for (int i = 0; i < tokens.length; i++) {
365	            switch (tokens[i]) {
366	                case "ST" -> tokens[i] = "STREET";
367	                case "RD" -> tokens[i] = "ROAD";
368	                case "AVE" -> tokens[i] = "AVENUE";
369	                default -> { }
370	            }
371	        }
372	        return String.join(" ", tokens);
373	    }
374	
375	    /**
376	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
377	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
378	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
379	     * empty string.
380	     *
381	     * @param value the raw value (last name or address) as submitted
382	     * @return the normalized comparison key
383	     */
384	    private String normalizeForHousehold(String value) {
385	        if (value == null) {
386	            return "";
387	        }
388	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
389	    }
390	
391	    /**
392	     * Derives the stable shared household identifier for a household, keyed on the normalized last
393	     * name and address. Because it is a pure function of those normalized keys, every owner in the
394	     * same household deterministically computes the same value. The identifier is the first 12
395	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
396	     * (the separator prevents distinct name/address pairs from colliding).
397	     *
398	     * @param lastNameKey the normalized last-name comparison key
399	     * @param addressKey  the normalized address comparison key
400	     * @return the stable household identifier
401	     */
402	    private String householdId(String lastNameKey, String postcode) {
403	        String seed = lastNameKey + "|" + (postcode == null ? "" : postcode);
404	        try {
405	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
406	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
407	            StringBuilder sb = new StringBuilder(digest.length * 2);
408	            for (byte b : digest) {
409	                sb.append(String.format("%02x", b));
410	            }
411	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
412	        }
413	        catch (java.security.NoSuchAlgorithmException e) {
414	            throw new IllegalStateException("SHA-256 not available", e);
415	        }
416	    }
417	
418	    /**
419	     * The exact number of national (subscriber) digits required for a given country calling code,
420	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
421	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
422	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
423	     */
424	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
425	        java.util.Map.of("61", 9, "1", 10);
426	
427	    /**
428	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
429	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
430	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
431	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
432	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
433	     * is stored as {@code '+61412345678'}.
434	     *
435	     * <p>In addition, when the number's country code has a fixed national-number length (see
436	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
437	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
438	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
439	     *
440	     * @param telephone the raw telephone number as submitted
441	     * @return the normalized E.164 telephone number
442	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
443	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
444	     *         for its country code
445	     */
446	    private String normalizeTelephone(String telephone) {
447	        String raw = telephone == null ? "" : telephone.trim();
448	        String digits = raw.replaceAll("\\D", "");
449	        String e164;
450	        if (raw.startsWith("+")) {
451	            e164 = "+" + digits;
452	        } else {
453	            if (digits.startsWith("0")) {
454	                digits = digits.substring(1);
455	            }
456	            e164 = "+61" + digits;
457	        }
458	        int digitCount = e164.length() - 1;
459	        if (digitCount < 8 || digitCount > 15) {
460	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
461	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
462	        }
463	        validateNationalNumberLength(e164);
464	        return e164;
465	    }
466	
467	    /**
468	     * Validates that an E.164 number's national-number length is correct for its country code.
469	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
470	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
471	     * following it must match exactly. Country codes without a fixed length are left unchecked.
472	     *
473	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
474	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
475	     *         for the country code
476	     */
477	    private void validateNationalNumberLength(String e164) {
478	        String allDigits = e164.substring(1);
479	        String bestCode = null;
480	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
481	            if (allDigits.startsWith(code)
482	                    && (bestCode == null || code.length() > bestCode.length())) {
483	                bestCode = code;
484	            }
485	        }
486	        if (bestCode == null) {
487	            return;
488	        }
489	        int nationalLength = allDigits.length() - bestCode.length();
490	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
491	        if (nationalLength != required) {
492	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
493	                "Telephone for country code '+" + bestCode + "' must have " + required
494	                    + " national digits");
495	        }
496	    }
497	
498	    /**
499	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
500	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
501	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
502	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
503	     */
504	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
505	        "NSW", new int[] {2000, 2099},
506	        "VIC", new int[] {3000, 3099},
507	        "QLD", new int[] {4000, 4099});
508	
509	    /**
510	     * Validates an owner's optional postcode against their city's region. The postcode is only
511	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
512	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
513	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
514	     * postcode must fall within that region's inclusive range; a city with no known region accepts
515	     * any 4-digit postcode.
516	     *
517	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
518	     * @param city     the owner's city, used to derive the region whose range applies
519	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
520	     *         for the city's region
521	     */
522	    private void validatePostcode(String postcode, String city) {
523	        if (postcode == null) {
524	            return;
525	        }
526	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
527	        int[] range = REGION_POSTCODE_RANGES.get(region);
528	        if (range == null) {
529	            return;
530	        }
531	        int value = Integer.parseInt(postcode);
532	        if (value < range[0] || value > range[1]) {
533	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
534	                "Postcode " + postcode + " is not valid for region " + region);
535	        }
536	    }
537	
538	    /**
539	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
540	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
541	     * (absent) or already valid.
542	     *
543	     * @param email the email address as submitted, or {@code null} when absent
544	     * @return the lower-cased email, or {@code null} when absent
545	     */
546	    private String normalizeEmail(String email) {
547	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
548	    }
549	
550	    /**
551	     * The set of disposable email domains an owner's email may not use. These throwaway-mailbox
552	     * providers are rejected because they cannot be relied on for durable contact.
553	     */
554	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
555	        "mailinator.com", "tempmail.com", "guerrillamail.com");
556	
557	    /**
558	     * Rejects an owner whose email domain is on the disposable-domain blocklist. The email has
559	     * already been normalized to lower-case, so the domain (the part after the last {@code '@'}) is
560	     * compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}. A {@code null} email
561	     * (absent) is accepted, keeping the field optional.
562	     *
563	     * @param email the normalized email address, or {@code null} when absent
564	     * @throws ResponseStatusException with a 400 status when the email domain is blocklisted
565	     */
566	    private void validateEmailDomain(String email) {
567	        if (email == null) {
568	            return;
569	        }
570	        int at = email.lastIndexOf('@');
571	        if (at < 0) {
572	            return;
573	        }
574	        String domain = email.substring(at + 1);
575	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
576	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
577	                "Email domain " + domain + " is not allowed");
578	        }
579	    }
580	
581	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
582	    @Override
583	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
584	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
585	        if (currentOwner == null) {
586	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
587	        }
588	        currentOwner.setAddress(ownerFieldsDto.getAddress());
589	        currentOwner.setCity(ownerFieldsDto.getCity());
590	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
591	        currentOwner.setLastName(ownerFieldsDto.getLastName());
592	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
593	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
594	        this.clinicService.saveOwner(currentOwner);
595	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
596	    }
597	
598	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
599	    @Transactional
600	    @Override
601	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
602	        Owner owner = this.clinicService.findOwnerById(ownerId);
603	        if (owner == null) {
604	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
605	        }
606	        // Soft delete: flag the owner deleted and retain the row rather than removing it.
607	        owner.setDeleted(true);
608	        this.clinicService.saveOwner(owner);
609	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
610	    }
611	
612	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
613	    @Override
614	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
615	        Owner owner = this.clinicService.findOwnerById(ownerId);
616	        if (owner == null) {
617	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
618	        }
619	        HttpHeaders headers = new HttpHeaders();
620	        Pet pet = petMapper.toPet(petFieldsDto);
621	        owner.setId(ownerId);
622	        pet.setOwner(owner);
623	        pet.getType().setName(null);
624	        this.clinicService.savePet(pet);
625	        PetDto petDto = petMapper.toPetDto(pet);
626	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
627	            .buildAndExpand(pet.getId()).toUri());
628	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
629	    }
630	
631	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
632	    @Override
633	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
634	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
635	        if (currentOwner != null) {
636	            Pet currentPet = this.clinicService.findPetById(petId);
637	            if (currentPet != null) {
638	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
639	                currentPet.setName(petFieldsDto.getName());
640	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
641	                this.clinicService.savePet(currentPet);
642	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
643	            }
644	        }
645	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
646	    }
647	
648	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
649	    @Override
650	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
651	        HttpHeaders headers = new HttpHeaders();
652	        Visit visit = visitMapper.toVisit(visitFieldsDto);
653	        Pet pet = new Pet();
654	        pet.setId(petId);
655	        visit.setPet(pet);
656	        this.clinicService.saveVisit(visit);
657	        VisitDto visitDto = visitMapper.toVisitDto(visit);
658	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
659	            .buildAndExpand(visit.getId()).toUri());
660	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
661	    }
662	
663	
664	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
665	    @Override
666	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
667	        Owner owner = this.clinicService.findOwnerById(ownerId);
668	        if (owner != null) {
669	            Pet pet = owner.getPet(petId);
670	            if (pet != null) {
671	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
672	            }
673	        }
674	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
675	    }
676	}
